    ]},
  {"no": 4, "title": "인장을 돌려주다", "giver": {"npc": "세드릭 몰", "place": "린도르"},
    "steps": [
      {"action": "이동", "npc": null, "place": "린도르", "item": null, "desc": "왕궁이 있는 린도르로 돌아간다."},
